<?php require_once '../config.php'; $a=$_GET['action']??'me';
if($a==='health'){db()->query('SELECT 1');$u=(bool)db()->query("SHOW TABLES LIKE 'users'")->fetch();$t=(bool)db()->query("SHOW TABLES LIKE 'tasks'")->fetch();out(['ok'=>true,'db'=>DB_NAME,'tables'=>$u&&$t]);}
if($a==='me'){if(empty($_SESSION['user']))out(['ok'=>true,'user'=>null]);$s=db()->prepare('SELECT id,name,email FROM users WHERE id=?');$s->execute([$_SESSION['user']]);out(['ok'=>true,'user'=>$s->fetch(),'csrf'=>csrf()]);}
if($_SERVER['REQUEST_METHOD']!=='POST')out(['ok'=>false,'error'=>'Método inválido'],405);$d=body();
if($a==='register'){$n=trim($d['name']??'');$e=strtolower(trim($d['email']??''));$p=$d['password']??'';if(strlen($n)<2||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($p)<8)out(['ok'=>false,'error'=>'Preencha nome, e-mail válido e senha com 8+ caracteres.'],422);try{$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$n,$e,password_hash($p,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=(int)db()->lastInsertId();out(['ok'=>true,'user'=>['id'=>$_SESSION['user'],'name'=>$n,'email'=>$e],'csrf'=>csrf()]);}catch(PDOException $x){if(($x->errorInfo[1]??0)==1062)out(['ok'=>false,'error'=>'Este e-mail já está cadastrado.'],409);out(['ok'=>false,'error'=>'Não foi possível criar o usuário no banco.'],500);}}
if($a==='login'){$e=strtolower(trim($d['email']??''));$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$e]);$u=$s->fetch();if(!$u||!password_verify($d['password']??'',$u['password_hash']))out(['ok'=>false,'error'=>'E-mail ou senha incorretos. Se é o primeiro acesso, use Criar conta.'],401);session_regenerate_id(true);$_SESSION['user']=(int)$u['id'];out(['ok'=>true,'user'=>['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email']],'csrf'=>csrf()]);}
if($a==='logout'){check();session_destroy();out(['ok'=>true]);} out(['ok'=>false,'error'=>'Ação inválida'],404); ?>